import java.sql.*;import java.util.*;
public final class SurchargeSlabStore {public record Slab(String name,double from,double to,double rate){}private static final List<Slab> DEFAULTS=List.of(new Slab("Up to 50 Lakh",0,5000000,0),new Slab("50 Lakh to 1 Crore",5000001,10000000,10),new Slab("1 Crore to 2 Crore",10000001,20000000,15),new Slab("2 Crore to 5 Crore",20000001,50000000,25),new Slab("Above 5 Crore",50000001,99999999,25));static{migrate();}private SurchargeSlabStore(){}
 private static void migrate(){TaxSlabStore.list();}
 public static synchronized List<Slab> list(){List<Slab> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c==null?null:c.prepareStatement("SELECT slab_name,from_amount,to_amount,tax_rate FROM settings_tax_slabs WHERE slab_type='SURCHARGE' AND is_deleted=0 ORDER BY slab_id")){if(p!=null){ResultSet r=p.executeQuery();while(r.next())out.add(new Slab(r.getString(1),r.getDouble(2),r.getDouble(3),r.getDouble(4)));}}catch(SQLException ignored){}return out.isEmpty()?new ArrayList<>(DEFAULTS):out;}
 public static synchronized void save(List<Slab> slabs){try(Connection c=DBConnection.getConnection()){if(c==null)return;c.setAutoCommit(false);try(PreparedStatement hide=c.prepareStatement("UPDATE settings_tax_slabs SET is_deleted=1,deleted_at=CURRENT_TIMESTAMP WHERE slab_type='SURCHARGE' AND is_deleted=0");PreparedStatement revive=c.prepareStatement("UPDATE settings_tax_slabs SET from_amount=?,to_amount=?,tax_rate=?,is_deleted=0,deleted_at=NULL WHERE slab_name=? AND slab_type='SURCHARGE'");PreparedStatement add=c.prepareStatement("INSERT INTO settings_tax_slabs(slab_name,from_amount,to_amount,tax_rate,slab_type,is_deleted) VALUES(?,?,?,?, 'SURCHARGE',0)")){hide.executeUpdate();for(Slab s:slabs){revive.setDouble(1,s.from());revive.setDouble(2,s.to());revive.setDouble(3,s.rate());revive.setString(4,s.name());if(revive.executeUpdate()==0){add.setString(1,s.name());add.setDouble(2,s.from());add.setDouble(3,s.to());add.setDouble(4,s.rate());add.executeUpdate();}}}c.commit();}catch(SQLException ignored){}}
}
